// Custos observation log. Records the Shepherd's observation comments when they
// are made, in one living PR comment, so they are not left to be remembered and
// written up afterwards.
// Plan: docs/plans/202610070939-cue-sigil-and-living-observation-plan.md (Phase 3).
// This is the capture half only. It does not build the observation, archive it at
// merge, tick the observed box or gate the seal.
//
// A workflow calls it after a checkout:
//   const log = require('./.github/scripts/observation-log.js');
//
// What counts: a review body, a review comment or a PR comment from the owner that
// has `shepherd observation` at the start of a line, with an optional 12-digit stamp
// after it (`shepherd observation 202610171524`). Quoted text, code, comments that
// carry the Claude Code footer (a navigo writing under the owner's login) and
// anything from a bot or a non-owner are skipped, the same rules the cue parser uses.
//
// The typed stamp is kept exactly as written. It has been local (Pacific) time, while
// the repo's records are UTC, so the row also carries GitHub's own posted time in UTC.
// Nothing here converts one to the other.
//
// This module only reads text and builds text. It never posts, labels or merges.

const { strip } = require('./cue-parser.js');

const MARKER = '<!-- custos-observation-log -->';
const LOG_START = '<!-- obs-log-start -->';
const LOG_END = '<!-- obs-log-end -->';

const FOOTERS = ['generated by [claude code]', 'generated with [claude code]'];
const hasFooter = (text) => FOOTERS.some((f) => String(text).toLowerCase().includes(f));

// `shepherd observation`, whole words, at the start of a line (up to three spaces in).
// Four spaces or a tab is indented code, which strip() has already removed.
const MARKER_RE = /^ {0,3}shepherd[ \t]+observation(?![A-Za-z0-9_])[ \t]*(.*)$/i;
// Exactly 12 digits. 11 or 13 are not a stamp; they stay in the text.
const STAMP_RE = /^(\d{12})(?!\d)[ \t]*[:.\-\u2013\u2014]*[ \t]*/;
const LEAD_SEP_RE = /^[:.\-\u2013\u2014]+[ \t]*/;

const ROW_ID_RE = /^[a-z]+-\d+$/;
const ROW_RE = /^\| .*<!--obs:([a-z]+-\d+)--> \|$/;
const EXCERPT_MAX = 240;
const INLINE_LINKS_MAX = 5;

const reject = (reason) => ({ ok: false, reason });

// Keep a comment's words in a table cell without letting them break the table, forge a
// row id, close a marker or ping someone. Truncate before escaping so an escape is
// never cut in half.
function makeExcerpt(text, max = EXCERPT_MAX) {
  let s = String(text).replace(/\s+/g, ' ').trim().replace(/</g, '&lt;');
  const chars = Array.from(s);
  if (chars.length > max) s = chars.slice(0, max).join('').trimEnd() + '\u2026';
  return s.replace(/\|/g, '\\|').replace(/@/g, '@\u200b');
}

function parseObservation(body, { association, authorType } = {}) {
  if (authorType === 'Bot') return reject('bot');
  if (association !== 'OWNER') return reject('not the owner');
  const raw = String(body || '');
  if (hasFooter(raw)) return reject('carries the Claude Code footer');
  const lines = strip(raw).split('\n');
  const at = lines.findIndex((l) => MARKER_RE.test(l));
  if (at === -1) return reject('no marker at the start of a line');
  const rest = lines[at].match(MARKER_RE)[1].replace(LEAD_SEP_RE, '');
  const sm = rest.match(STAMP_RE);
  const stamp = sm ? sm[1] : null;
  const first = sm ? rest.slice(sm[0].length) : rest;
  const text = [first, ...lines.slice(at + 1)].join('\n').trim();
  return { ok: true, stamp, text, excerpt: makeExcerpt(text) };
}

// UTC, YYYYMMDDHHMM: the repo's prima-clock form.
function utcStamp(date) {
  const d = new Date(date);
  const p = (n, w = 2) => String(n).padStart(w, '0');
  return `${p(d.getUTCFullYear(), 4)}${p(d.getUTCMonth() + 1)}${p(d.getUTCDate())}` +
    `${p(d.getUTCHours())}${p(d.getUTCMinutes())}`;
}

const isGithubUrl = (u) => typeof u === 'string' && u.startsWith('https://github.com/');
const link = (label, url) => (isGithubUrl(url) ? `[${label}](${url})` : label);

function inlineNote(list) {
  if (!list || !list.length) return '';
  const shown = list.slice(0, INLINE_LINKS_MAX).map((c, i) => link(String(i + 1), c.url));
  const more = list.length > INLINE_LINKS_MAX ? ` \u2026+${list.length - INLINE_LINKS_MAX}` : '';
  return ` \u00b7 ${list.length} inline: ${shown.join(' ')}${more}`;
}

const KIND_LABEL = { review: 'review', comment: 'comment', inline: 'inline comment' };

// One table row. The id (kind-number) is hidden at the end so an edit replaces its row.
function buildRow({ id, kind, url, by, posted, stamp, head, excerpt, inline = [], edited = false }) {
  if (!ROW_ID_RE.test(String(id))) throw new Error(`bad row id: ${id}`);
  const label = KIND_LABEL[kind] || 'comment';
  const who = /^[A-Za-z0-9_[\]-]+$/.test(String(by)) ? by : '?';
  const sha = /^[0-9a-f]{7,40}$/i.test(String(head)) ? String(head).slice(0, 7) : '?';
  const note = (excerpt || '(no text)') + inlineNote(inline) + (edited ? ' \u00b7 edited' : '');
  const line = `| ${utcStamp(posted)} | ${stamp || '\u2014'} | ${link(label, url)} | @${who} | ` +
    `\`${sha}\` | ${note} <!--obs:${id}--> |`;
  return { id, line };
}

// Rows already in a log comment, found by their hidden id. Anything else in the body
// (hand edits, the intro) is ignored, so a tidied comment still keeps its rows.
function parseRows(body) {
  return String(body || '').split('\n').map((line) => {
    const m = line.match(ROW_RE);
    return m ? { id: m[1], line } : null;
  }).filter(Boolean);
}

function render(rows) {
  return [
    MARKER,
    '### Observation log',
    '',
    'Each \u201cshepherd observation\u201d review or comment, recorded when it was made. ' +
      'An edit updates its row; a deletion leaves the row in place.',
    '',
    '| posted (UTC) | typed stamp | what | by | head | note |',
    '|---|---|---|---|---|---|',
    LOG_START,
    ...rows.map((r) => r.line),
    LOG_END,
    '',
    'The typed stamp is exactly as written (so far local, Pacific time); the posted time is ' +
      'GitHub\u2019s, in UTC. Nothing here converts one to the other.',
    '',
  ].join('\n');
}

// Add a row, or replace the row with the same id (an edit). Order of first appearance
// is kept. Applying the same row twice gives the same body.
function mergeLog(oldBody, row) {
  const rows = parseRows(oldBody);
  const at = rows.findIndex((r) => r.id === row.id);
  if (at === -1) rows.push(row); else rows[at] = row;
  return { body: render(rows), rows };
}

// What the workflow reads from a webhook payload. The three events carry the same facts
// under different names: a review has submitted_at and a commit_id, a review comment has
// a commit_id, a PR comment (an issue_comment) has neither and the head must be asked for.
// Returns null for an event this log does not read (including a comment on a plain issue).
const prNumberOf = (p) => (p.pull_request ? p.pull_request.number : undefined);

// One small reader per event: what it calls the comment, its kind and its number.
function fromReview(p) {
  const c = p.review;
  return c && { c, kind: 'review', prNumber: prNumberOf(p), id: `review-${c.id}`,
    posted: c.submitted_at, head: c.commit_id, reviewId: c.id };
}

function fromReviewComment(p) {
  const c = p.comment;
  return c && { c, kind: 'inline', prNumber: prNumberOf(p), id: `rcomment-${c.id}`,
    posted: c.created_at, head: c.commit_id };
}

function fromPrComment(p) {
  const c = p.comment;
  if (!c || !p.issue || !p.issue.pull_request) return null;
  return { c, kind: 'comment', prNumber: p.issue.number, id: `comment-${c.id}`, posted: c.created_at };
}

// A Map, not a plain object, so an event named `constructor` finds nothing.
const READERS = new Map([
  ['pull_request_review', fromReview],
  ['pull_request_review_comment', fromReviewComment],
  ['issue_comment', fromPrComment],
]);

function readEvent(eventName, payload) {
  const p = payload || {};
  const read = READERS.get(eventName);
  const part = read ? read(p) : null;
  if (!part || !part.prNumber) return null;
  const c = part.c;
  return {
    id: part.id, kind: part.kind, prNumber: part.prNumber,
    reviewId: part.reviewId ?? null, head: part.head ?? null, posted: part.posted,
    url: c.html_url, body: c.body,
    by: c.user && c.user.login, authorType: c.user && c.user.type,
    association: c.author_association,
    edited: p.action === 'edited',
  };
}

module.exports = {
  parseObservation, makeExcerpt, utcStamp, buildRow, inlineNote, parseRows, mergeLog, render,
  readEvent, MARKER, LOG_START, LOG_END, EXCERPT_MAX, INLINE_LINKS_MAX,
};
